// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 unusedParam) internal {
        vm.assume(unusedParam == unusedParam);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        assertTrue(reverted || (balAfter == 0 && balBefore >= 0));
    }

    function testFuzz_run(uint256 unusedParam) public {
        _run(unusedParam);
    }

    receive() external payable {}
}
